ALTER TABLE cursos ADD COLUMN origen_original VARCHAR(150) NULL, ADD UNIQUE KEY cursos_origen_original (origen_original), MODIFY modalidad ENUM('presencial','virtual','hibrida') NULL, MODIFY duracion VARCHAR(120) NULL, ADD COLUMN area VARCHAR(80) NULL, ADD COLUMN certificacion VARCHAR(150) NULL, ADD COLUMN icono VARCHAR(30) NULL, ADD COLUMN color VARCHAR(20) NOT NULL DEFAULT 'indigo', ADD COLUMN orden INT NOT NULL DEFAULT 0;
ALTER TABLE servicios ADD COLUMN origen_original VARCHAR(150) NULL, ADD UNIQUE KEY servicios_origen_original (origen_original), ADD COLUMN presentacion VARCHAR(30) NOT NULL DEFAULT 'normal', ADD COLUMN nombre_corto VARCHAR(80) NULL, ADD COLUMN destacado VARCHAR(100) NULL, ADD COLUMN dato_principal VARCHAR(40) NULL, ADD COLUMN dato_secundario VARCHAR(100) NULL, ADD COLUMN etiquetas TEXT NULL, ADD COLUMN icono VARCHAR(30) NULL, ADD COLUMN color VARCHAR(20) NOT NULL DEFAULT 'indigo', ADD COLUMN orden INT NOT NULL DEFAULT 0;
ALTER TABLE galeria_items ADD COLUMN origen_original VARCHAR(150) NULL, ADD UNIQUE KEY galeria_origen_original (origen_original);
